import math

def predict(probe):
    # Beliefs:
    # - For x > 0, output is 52.2 [E1, E2, E3, E4, E6, E8, E10, E12]
    # - For x < 0, output is -14.96 [E1, E2, E3, E4, E5, E6, E7, E8, E9, E10, E11, E12]
    # - For x == 0, output is 898156.8 [E4, E6, E12]
    # - Boundary is exactly at 0: 1e-15 -> 52.2, -1e-15 -> -14.96 [E12]
    #   so no epsilon region; it's a pure sign test with a special zero case.
    xs = probe.get("x", [])
    ys = []
    for x in xs:
        if x is None:
            ys.append(None)
        elif x > 0:
            ys.append(52.2)
        elif x < 0:
            ys.append(-14.96)
        else:
            ys.append(898156.8)
    return {"y": ys}
